CREATE OR ALTER function [dbo].[CheckIfObjectExists]
(
	@ObjectType varchar(50), 
	@ObjectTypeID int, 
	@ObjectID int, 
	@Fields nvarchar(max) 
)
returns bit
as
begin
	declare @result bit = 0;
	select @result = [dbo].[CheckIfObjectExistsWithParent] (@ObjectType, @ObjectTypeID, @ObjectID, @Fields, default)

	return @result;
end
